package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class MixedOperationOrderTest {
 @Test public void allTwelveShapesCheckPriorityIntermediateAndPublicAnswer(){
  String[] prompts={"2 + 3 × 4","(2 + 3) × 4","20 - 3 × 4","(20 - 3) × 4","2 + 12 ÷ 4","(2 + 10) ÷ 4","20 - 12 ÷ 4","(20 - 8) ÷ 4","12 × 3 ÷ 4","12 ÷ 3 × 4","12 + 3 - 4","12 - 3 + 4"};long[][] values={{3,4,12,2,12,14},{2,3,5,5,4,20},{3,4,12,20,12,8},{20,3,17,17,4,68},{12,4,3,2,3,5},{2,10,12,12,4,3},{12,4,3,20,3,17},{20,8,12,12,4,3},{12,3,36,36,4,9},{12,3,4,4,4,16},{12,3,15,15,4,11},{12,3,9,9,4,13}};
  String[] priority={"right","brackets","right","brackets","right","brackets","right","brackets","left","left","left","left"};Checker checker=new Checker();
  for(int i=0;i<prompts.length;i++){Question q=new Question("mixed",prompts[i],"poison","poison");q.stepSupport=false;assertTrue(checker.check(q,List.of(),List.of(""+values[i][5])).correct());assertEquals(Checker.Status.WRONG_ANSWER,checker.check(q,List.of(),List.of(""+(values[i][5]+1))).status);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));assertTrue(h.step(0).accepts(priority[i]));for(int j=0;j<6;j++){assertTrue(h.step(j+1).accepts(""+values[i][j]));assertFalse(h.step(j+1).before.matches(".*[0-9].*"));assertFalse(h.step(j+1).accepts(""+(values[i][j]+1)));}}
 }
 @Test public void normalYearSixSupplyAndInvalidPublicExpressions(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(p).inGrade("mixed",6));Generator gen=new Generator(new Random(197));CurriculumLimits limits=GlobalCurriculum.limits(p.educationSystem,"mixed",6);List<String> recent=new ArrayList<>();Set<String> shapes=new HashSet<>();for(int i=0;i<150;i++){Question q=gen.next("mixed",recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());shapes.add(q.prompt.replaceAll("[0-9]+","n"));assertNotNull(MixedOperationOrder.read(q));q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(Expression.number(q.prompt).toString())).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(12,shapes.size());for(String prompt:List.of("(2+3*4","2+3)*4","2+3/0","2+3/2","2-3*4","999999999999999999+3*4","2+3+4"))assertNull(MixedOperationOrder.read(new Question("mixed",prompt,"","14")));}
}
